/**
 * Unit tests for FastDateFormat.applyRules.
 * Since applyRules is protected and uses a private field mRules,
 * we use reflection to inject mock rules to test the logic.
 */
@RunWith(MockitoJUnitRunner.class)
public class FastDateFormat_applyRules_TriageGen0Test {

    @Test
    public void testApplyRules_Success() throws Exception {
        // Arrange
        // Using a specific pattern to ensure mRules is initialized via the constructor
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Prefix: ");

        // We need to access the internal mRules field. 
        // Since mRules is private/protected within the class, we use reflection to mock it.
        Rule mockRule1 = mock(Rule.class);
        Rule mockRule2 = mock(Rule.class);
        Rule[] mockRules = new Rule[]{mockRule1, mockRule2};

        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, mockRules);

        // Set expectation: rule 1 appends "A", rule 2 appends "B"
        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("A");
            return null;
        }).when(mockRule1).appendTo(eq(buf), eq(calendar));

        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("B");
            return null;
        }).when(mockRule2).appendTo(eq(buf), eq(calendar));

        // Act
        // Reflectively call the protected method applyRules
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("Prefix: AB", result.toString());
        assertSame(buf, result);
        verify(mockRule1, times(1)).appendTo(buf, calendar);
        verify(mockRule2, times(1)).appendTo(buf, calendar);
    }

    @Test
    public void testApplyRules_EmptyRules() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Start");

        // Inject empty rules array
        Rule[] emptyRules = new Rule[0];
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, emptyRules);

        // Act
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("Start", result.toString());
        assertSame(buf, result);
    }

    @Test(expected = Exception.class)
    public void testApplyRules_NullRulesThrowsException() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();

        // Inject null rules to trigger NullPointerException in the loop (len = mRules.length)
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, null);

        // Act
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        applyRulesMethod.invoke(fdf, calendar, buf);

        // Assert handled by expected exception
    }
}
